def change_base(x: int, base: int) -> str:
    if x == 0:
        return "0"
    digits = []
    while x > 0:
        digits.append(str(x % base))
        x //= base
    return ''.join(reversed(digits))

def change_base(x: int, base: int) -> str:
    if x == 0:
        return "0"
    digits = []
    negative = x < 0
    x = abs(x)
    while x > 0:
        digits.append(str(x % base))
        x //= base
    if negative:
        digits.append('-')
    return ''.join(reversed(digits))

def fib4(n: int) -> int:
    if n < 2:
        return 0
    if n == 2:
        return 2
    if n == 3:
        return 0

    a, b, c, d = 0, 0, 2, 0
    for _ in range(4, n + 1):
        a, b, c, d = b, c, d, a + b + c + d
    return d

