def modp(n: int, p: int) -> int:
    if p == 1:
        return 0
    result = 1
    base = 2 % p
    exp = n
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % p
        base = (base * base) % p
        exp //= 2
    return result

def decode_shift(s: str) -> str:
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            shifted = chr((ord(ch) - ord('a') - 5) % 26 + ord('a'))
            result.append(shifted)
        else:
            result.append(ch)
    return ''.join(result)

def decode_shift(s: str) -> str:
    """
    Decode a string where each lowercase letter was shifted forward by 5 positions.
    To decode, shift each letter backward by 5 positions in the alphabet.
    """
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            # Shift backward by 5, wrapping around the alphabet
            decoded_char = chr((ord(ch) - ord('a') - 5) % 26 + ord('a'))
            result.append(decoded_char)
        else:
            # Non-lowercase letters are kept unchanged (though specification says lowercase input)
            result.append(ch)
    return ''.join(result)

def decode_shift(s: str) -> str:
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            shifted = ord(ch) - 5
            if shifted < ord('a'):
                shifted += 26
            result.append(chr(shifted))
        else:
            result.append(ch)
    return ''.join(result)

def decode_shift(s: str) -> str:
    """
    Decodes a string where each letter was shifted forward by 5 positions.
    To decode, shift each letter backward by 5 positions in the alphabet.
    """
    result = []
    for char in s:
        if 'a' <= char <= 'z':
            decoded_char = chr((ord(char) - ord('a') - 5) % 26 + ord('a'))
            result.append(decoded_char)
        else:
            result.append(char)
    return ''.join(result)

