def circular_shift(x: int, shift: int) -> str:
    digits = str(x)
    n = len(digits)

    if shift > n:
        return digits[::-1]

    shift = shift % n
    if shift == 0:
        return digits

    return digits[-shift:] + digits[:-shift]

def circular_shift(x: int, shift: int) -> str:
    s = str(x)
    n = len(s)
    if shift > n:
        return s[::-1]
    shift = shift % n
    if shift == 0:
        return s
    return s[-shift:] + s[:-shift]

