def decimal_to_binary(decimal: int) -> str:
    binary_str = ""
    n = decimal
    if n == 0:
        binary_str = "0"
    else:
        while n > 0:
            binary_str = str(n % 2) + binary_str
            n //= 2
    return "db" + binary_str + "db"

def is_happy(s: str) -> bool:
    if len(s) < 3:
        return False
    for i in range(len(s) - 2):
        if s[i] == s[i + 1] or s[i] == s[i + 2] or s[i + 1] == s[i + 2]:
            return False
    return True

